-- 쏠 웰니스 하우스 유형 참고 테이블 (20개 전체)
-- lib/data.ts의 TYPES와 내용이 동일합니다 — 앱은 이 테이블을 읽지 않고 lib/data.ts를 그대로 쓰지만,
-- 콘텐츠 검토/공유, 그리고 나중에 base_knowledge를 DB 기반으로 바꾸고 싶을 때를 위한 참고용 테이블입니다.
-- 심층 리포트의 base_knowledge(lib/base-knowledge.ts)는 지금도 이 내용과 같은 code/name/blurb/traits를
-- 그대로 사용해서 AI에게 참고자료로 전달하고 있습니다 — 신규 10개 유형도 자동으로 포함됩니다.
create table if not exists public.ssol_dessert_types (
  type_key    text primary key,
  domain      text not null,
  style       text not null check (style in ('F','E')),
  intensity   text not null check (intensity in ('clear','blend')),
  name        text not null,
  code        text not null,
  icon        text not null,
  blurb       text not null,
  traits      text[] not null
);

insert into public.ssol_dessert_types (type_key, domain, style, intensity, name, code, icon, blurb, traits) values
  ('relate_F', 'relate', 'F', 'clear', '딸기마카롱', '상큼하고 발랄하게, 먼저 다가가는 성향', 'macaron', '당신은 관계 속에서 먼저 손을 내미는 사람입니다. 갈등이 생겨도 피하지 않고 대화로 풀어가려 하고, 새로운 사람 앞에서도 자연스럽게 먼저 다가갑니다. 그 적극성 덕분에 주변에서 늘 든든한 사람으로 여겨지곤 해요. 다만 가끔은, 혼자 남겨지는 것에 대한 불안이 그 부지런함 뒤에 숨어 있진 않은지 살펴봐도 좋겠어요.', ARRAY['관계에서 먼저 다가가는 편', '갈등은 대화로 빨리 풀려고 함', '새로운 사람과도 쉽게 친해짐', '혼자보다 함께 있는 게 편함', '연락이 뜸해지면 불안해짐']),
  ('relate_E', 'relate', 'E', 'clear', '슈크림빵', '담백한 겉과 달리 속은 부드럽고 여린 성향', 'creambun', '당신은 혼자만의 시간에서 편안함을 느끼는 사람입니다. 관계에서 먼저 다가가기보다 상대가 다가와주길 기다리는 편이고, 그래서 종종 쿨하다는 인상을 줍니다. 하지만 그 안에는 관계에 대한 조용한 갈망도 함께 자리하고 있어요. 편안한 거리감과 솔직한 마음 사이에서 균형을 찾아가는 연습이 도움이 될 수 있어요.', ARRAY['혼자만의 시간이 편함', '관계는 상대가 먼저 다가오길 기다림', '감정 표현이 서툰 편', '갈등 상황은 조용히 피함', '마음을 여는 데 시간이 걸림']),
  ('worth_F', 'worth', 'F', 'clear', '밀푀유', '겹겹이 쌓아올리며 스스로를 채워가는 성향', 'millefeuille', '당신은 부족함을 느끼는 순간 즉시 채우려고 움직이는 사람입니다. 자격증이든 프로젝트든 끊임없이 스스로를 성장시켜가는 힘이 뚜렷합니다. 그 힘이 지금의 당신을 만든 가장 큰 자산이기도 해요. 다만 이만하면 충분하다고 스스로에게 말해주는 순간이 얼마나 있었는지도 함께 돌아보면 좋겠어요.', ARRAY['부족함을 느끼면 바로 채우려 함', '목표 지향적이고 성장에 진심', '스스로에게 기준이 높은 편', '성취해도 다음 목표부터 생각함', '인정받는 것에 예민한 편']),
  ('worth_E', 'worth', 'E', 'clear', '머랭쿠키', '겉은 바삭하고 예쁘지만 쉽게 부서지는 성향', 'meringue', '당신은 비교당하는 상황을 자연스럽게 피하며, 힘든 티를 잘 내지 않는 사람입니다. 겉으로는 늘 안정적이고 밝아 보이지만, 속으로는 자주 스스로를 의심하고 있을 수 있습니다. 괜찮은 척 넘기는 습관이 당신을 지켜온 방식이었을 거예요. 이제는 그 서운함을 아주 조금씩이라도 꺼내보는 연습을 시작해봐도 좋겠어요.', ARRAY['비교되는 상황을 피하는 편', '힘든 티를 잘 내지 않음', '겉으로는 밝고 안정적으로 보임', '서운함을 마음에 담아두는 편', '인정보다 무난함을 택함']),
  ('control_F', 'control', 'F', 'clear', '티라미수', '층층이 정교하게 쌓아 완성하는, 계획적인 성향', 'tiramisu', '당신은 불확실한 상황일수록 계획을 세워 스스로 통제감을 만들어내는 사람입니다. 미리 준비하고 대비하는 힘이 뛰어나서, 주변에서 믿음직스럽다는 말을 자주 들을 겁니다. 그런데 계획대로 되지 않는 순간, 유독 크게 흔들리고 있진 않으신가요? 통제할 수 없는 것과 함께 지내는 연습도 필요한 시점일 수 있어요.', ARRAY['미리 계획 세우는 걸 좋아함', '변화가 생기면 바로 대안을 찾음', '준비성이 철저한 편', '예상 밖의 상황에 스트레스 받음', '체계적인 걸 선호함']),
  ('control_E', 'control', 'E', 'clear', '카라멜푸딩', '부드럽게 흘러가는 대로 두는, 여유로운 성향', 'pudding', '당신은 서두르지 않고 흘러가는 대로 두는 걸 편안해하는 사람입니다. 유연하고 스트레스를 덜 받는 편이지만, 중요한 결정도 함께 미뤄지는 경향이 있습니다. 마감이 코앞에 닥쳐야 움직이게 되는 패턴, 익숙하신가요? 미루고 있는 것들 중 무엇이 진짜 부담인지 한 번쯤 들여다볼 때예요.', ARRAY['계획보다 흐름에 맡기는 편', '결정은 마감 직전에 내림', '미래 얘기를 미루는 경향', '스트레스를 비교적 덜 받는 편', '즉흥적인 상황을 편하게 여김']),
  ('happy_F', 'happy', 'F', 'clear', '요거트파르페', '층층이 좋은 순간을 쌓아 음미하는 성향', 'parfait', '당신은 좋은 순간을 그냥 흘려보내지 않고 의식적으로 붙잡아두는 사람입니다. 작은 성취에도 스스로를 축하할 줄 알고, 그 감각이 삶을 꾸준히 채워주고 있습니다. 주변 사람들에게도 긍정적인 에너지를 자연스럽게 전하는 편이에요. 다만 항상 밝은 모습만 보여주려다, 스스로의 지친 순간을 뒤늦게 알아차리고 있진 않은지도 살펴보면 좋겠어요.', ARRAY['좋은 순간을 오래 음미함', '작은 성취도 스스로 축하함', '긍정적인 에너지가 자연스러움', '감사한 마음을 자주 느낌', '분위기를 밝게 만드는 편']),
  ('happy_E', 'happy', 'E', 'clear', '에스프레소브라우니', '진하고 강하게, 멈추지 않고 나아가는 성향', 'brownie', '당신은 몸의 신호를 무시하고서라도 계속 밀어붙이는 힘이 강한 사람입니다. 책임감이 강해서 웬만해선 힘든 티를 내지 않고 앞으로 나아갑니다. 그 추진력 덕분에 많은 걸 이뤄왔을 거예요. 다만 많은 걸 해냈는데 정작 행복하지 않다는 감각이 자주 든다면, 잠깐 멈춰서 그 순간을 누리는 연습이 필요할 수 있어요.', ARRAY['성취해도 금방 다음으로 넘어감', '힘든 것도 티 내지 않고 밀어붙임', '책임감이 강한 편', '잠깐 멈추는 게 어려운 편', '목표 지향적이고 추진력 있음']),
  ('meaning_F', 'meaning', 'F', 'clear', '피스타치오크루아상', '겹겹이 새로운 결을 만들며 나아가는, 탐색하는 성향', 'croissant', '당신은 방향이 흐릿하게 느껴질 때 가만히 있지 못하고 적극적으로 답을 찾아 나서는 사람입니다. 새로운 도전을 두려워하지 않는 호기심이 큰 자산입니다. 그 탐색의 힘 덕분에 계속 성장해왔을 거예요. 다만 다음 스텝을 찾는 데 몰두하다, 지금 이 순간에 충분히 머무르지 못하고 있진 않은지 한번 짚어보면 좋겠어요.', ARRAY['새로운 도전을 두려워하지 않음', '방향이 흐릿하면 바로 답을 찾음', '호기심이 많고 성장 지향적', '익숙한 것에 쉽게 지루함을 느낌', '다음 단계를 계속 고민함']),
  ('meaning_E', 'meaning', 'E', 'clear', '카스텔라', '부들부들하고 무난하게, 안정을 추구하는 성향', 'castella', '당신은 익숙하고 안정적인 선택을 지키는 걸 편안해하는 사람입니다. 갈등을 크게 만들지 않고, 무던하게 상황을 받아들이는 힘이 있습니다. 그 안정감이 당신과 주변 모두를 편안하게 만들어줘요. 다만 중요한 결정을 계속 나중으로 미루다, 정작 원하는 방향을 놓치고 있진 않은지 살펴볼 시점일 수 있어요.', ARRAY['익숙하고 안정적인 선택 선호', '큰 결정은 미루는 편', '갈등을 크게 만들지 않음', '무난함 속에서 편안함을 느낌', '변화보다 지속을 택함']),
  ('relate_F_blend', 'relate', 'F', 'blend', '딸기쇼트케이크', '다가가고 싶지만, 때로는 거리를 두기도 하는 성향', 'shortcake', '당신은 관계에서 먼저 다가가는 편이지만, 언제나 그런 것은 아닙니다. 마음이 내킬 때는 자연스럽게 손을 내밀다가도, 어떤 날은 한 발 물러서서 지켜보는 쪽을 택하기도 해요. 이런 유연함 덕분에 상대나 상황에 따라 다르게 반응할 수 있는 여유가 있습니다. 다만 스스로도 언제 다가가고 언제 물러서는지 그 기준이 헷갈릴 때가 있을 수 있어요.', ARRAY['기분에 따라 관계에서의 적극성이 달라짐', '먼저 다가가지만 매번은 아님', '상황을 보고 다가갈 타이밍을 조절함', '때로는 적극적으로, 때로는 조용히 지켜봄', '관계의 온도를 유연하게 맞춰감']),
  ('relate_E_blend', 'relate', 'E', 'blend', '바닐라빈 판나코타', '혼자가 편하면서도, 가끔은 다가가고 싶은 성향', 'pannacotta', '당신은 혼자 있는 시간이 편안하게 느껴지지만, 그렇다고 늘 거리를 두는 것은 아닙니다. 어떤 순간에는 스스로도 놀랄 만큼 먼저 다가가기도 해요. 이 두 가지 모습이 공존하는 건 자연스러운 일이지, 일관성이 없다는 뜻은 아니에요. 다만 상대는 가끔 당신의 온도차를 종잡기 어려워할 수 있습니다.', ARRAY['혼자만의 시간과 함께하는 시간을 오가며 균형을 찾음', '가끔은 예상 밖으로 먼저 다가감', '관계의 거리 조절이 상황마다 달라짐', '친해지는 속도가 들쑥날쑥한 편', '마음을 여는 데 걸리는 시간이 그때그때 다름']),
  ('worth_F_blend', 'worth', 'F', 'blend', '베리치즈케이크', '채우려 하면서도, 가끔은 쉬어가는 성향', 'berrycheesecake', '당신은 부족함이 느껴질 때 채우려는 마음이 있지만, 늘 그 마음에 쫓기지는 않습니다. 목표를 세우고 노력하다가도, 어떤 날은 "오늘은 여기까지"라며 스스로에게 여유를 허락해요. 이 균형 감각 덕분에 지치지 않고 오래 갈 수 있는 힘이 있습니다. 다만 그 기준이 명확하지 않아 스스로도 언제 밀어붙이고 언제 쉬어야 할지 헷갈릴 때가 있을 수 있어요.', ARRAY['성취를 추구하지만 완벽까지는 아님', '노력과 휴식 사이를 오감', '때로는 목표지향적, 때로는 여유로움', '스스로에게 관대해지는 순간이 있음', '밀어붙이는 강도가 상황마다 다름']),
  ('worth_E_blend', 'worth', 'E', 'blend', '레몬 머랭 타르트', '비교를 피하고 싶으면서도, 가끔은 부딪혀보는 성향', 'lemontart', '당신은 비교당할 만한 상황을 웬만하면 피하고 싶지만, 때로는 스스로도 의외다 싶을 만큼 정면으로 부딪혀보기도 합니다. 부서지기 쉬운 겉면 아래 단단한 기반이 있는 것처럼, 여린 듯 보여도 필요한 순간엔 버텨내는 힘이 있어요. 이 두 모습이 함께 있다는 건 상황을 유연하게 읽고 있다는 뜻이기도 합니다.', ARRAY['평소엔 회피하지만 가끔 정면 대응함', '부담스러운 상황은 기본적으로 피하려 함', '필요할 땐 의외의 뚝심을 보임', '인정 욕구와 회피 사이를 오감', '컨디션에 따라 대응 방식이 달라짐']),
  ('control_F_blend', 'control', 'F', 'blend', '크렘브륄레', '계획하고 대비하면서도, 가끔은 흐름에 맡기는 성향', 'cremebrulee', '당신은 미리 계획하고 대비하는 걸 선호하지만, 언제나 철저하게 통제하려 하지는 않습니다. 단단한 겉면 아래 부드러운 속처럼, 겉으로는 체계적이어 보여도 상황에 따라 유연하게 놓아줄 줄 아는 여유가 있어요. 이 균형 덕분에 지나치게 긴장하지 않으면서도 준비된 상태를 유지할 수 있습니다.', ARRAY['계획을 세우지만 집착하지는 않음', '대비하면서도 여지를 남겨둠', '통제와 여유 사이를 오감', '예상 밖 변화에도 비교적 유연하게 대응함', '긴장과 이완을 스스로 조절함']),
  ('control_E_blend', 'control', 'E', 'blend', '퐁당 쇼콜라', '차분해 보이지만, 속엔 뜨거운 감정이 쌓여있는 성향', 'fondant', '당신은 겉으로는 상황을 부드럽게 흘려보내는 것처럼 보이지만, 그 안에는 미처 다 드러내지 못한 감정이 쌓여있을 수 있습니다. 평소엔 침착하게 넘어가다가도, 어느 순간 예상치 못하게 마음이 왈칵 터져 나오는 경험을 해본 적 있을 거예요. 이는 감정을 못 다루는 게 아니라, 다루는 방식이 두 가지 속도로 움직인다는 뜻이에요.', ARRAY['평소엔 무던하게 넘기는 편', '감정을 안에 쌓아두는 경향이 있음', '가끔 예상 밖으로 감정이 터져 나옴', '겉모습과 속마음의 온도차가 있음', '쌓인 감정을 풀어낼 창구가 필요함']),
  ('happy_F_blend', 'happy', 'F', 'blend', '트라이플', '좋은 순간을 쌓아가면서도, 완벽하지 않아도 괜찮은 성향', 'trifle', '당신은 좋은 순간들을 쌓아가며 음미하는 편이지만, 그 순간들이 완벽하게 정돈되어 있을 필요는 없다고 느낍니다. 계획한 행복도 좋지만, 뒤죽박죽이어도 그 안에서 즐거움을 찾아내는 여유가 있어요. 이런 태도 덕분에 행복을 얻는 방식이 한 가지로 고정되어 있지 않습니다.', ARRAY['행복을 쌓아가되 형식에 얽매이지 않음', '계획된 즐거움과 즉흥적인 즐거움을 둘 다 좋아함', '완벽하지 않아도 만족할 줄 앎', '여러 즐거움을 한꺼번에 누리는 편', '즐기는 방식이 상황마다 다름']),
  ('happy_E_blend', 'happy', 'E', 'blend', '초콜릿 무스', '강하게 나아가면서도, 가끔은 가볍게 흘려보내는 성향', 'mousse', '당신은 진하고 강한 몰입으로 앞으로 나아가는 편이지만, 늘 그렇게 무겁게 힘을 주지는 않습니다. 어떤 날은 가볍게, 힘을 빼고 흘러가는 대로 두기도 해요. 그 덕분에 지치지 않고 자신만의 속도를 유지할 수 있습니다.', ARRAY['몰입하되 항상 무겁지는 않음', '강약을 스스로 조절하는 편', '가볍게 넘기는 날도 있음', '밀도 있는 날과 가벼운 날이 공존함', '자신만의 리듬을 찾아가는 중']),
  ('meaning_F_blend', 'meaning', 'F', 'blend', '바스크 치즈케이크', '새로운 길을 탐색하면서도, 완벽한 정답을 찾지는 않는 성향', 'basquecake', '당신은 새로운 결을 만들며 나아가는 걸 좋아하지만, 그 길이 반드시 완성된 형태일 필요는 없다고 느낍니다. 일부러 다듬지 않은 듯한 태도로, 시행착오 자체를 자연스럽게 받아들여요. 이런 태도 덕분에 방향을 찾아가는 과정 자체를 즐길 수 있습니다.', ARRAY['탐색하되 완벽한 답을 요구하지 않음', '시행착오를 자연스럽게 받아들임', '정돈되지 않은 과정도 괜찮다고 여김', '새로운 시도와 편안함을 오감', '방향을 찾아가는 과정 자체를 즐김']),
  ('meaning_E_blend', 'meaning', 'E', 'blend', '마들렌', '안정을 추구하면서도, 가끔은 새로운 것에 끌리는 성향', 'madeleine', '당신은 익숙하고 안정적인 것을 선호하지만, 가끔은 스스로도 의외다 싶을 만큼 새로운 것에 끌릴 때가 있습니다. 익숙한 형태 안에 작은 변주가 담겨 있는 것처럼, 안정 속에서도 소소한 변화를 즐길 줄 알아요. 이 균형 덕분에 지나치게 틀에 갇히지 않으면서도 편안함을 잃지 않을 수 있습니다.', ARRAY['안정을 추구하되 가끔 새로움에 끌림', '익숙함 속에서 작은 변화를 즐김', '큰 변화는 부담스럽지만 작은 변화는 반김', '안정과 호기심 사이를 오감', '예상 밖의 선택을 가끔 함'])
on conflict (type_key) do update set
  domain = excluded.domain, style = excluded.style, intensity = excluded.intensity,
  name = excluded.name, code = excluded.code, icon = excluded.icon,
  blurb = excluded.blurb, traits = excluded.traits;

alter table public.ssol_dessert_types enable row level security;
drop policy if exists "dessert types: public read" on public.ssol_dessert_types;
create policy "dessert types: public read" on public.ssol_dessert_types for select using (true);
